package com.mockarena.evaluation.application;
import com.mockarena.evaluation.domain.*; import com.mockarena.evaluation.infrastructure.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service public class CodingEvaluationJobService {
 private final CodingEvaluationJobRepository jobs; private final AssessmentSnapshotClient snapshots; private final QuestionCodingSpecClient specs; private final RunnerExecutionClient runner; private final Clock clock=Clock.systemUTC(); private final String owner=UUID.randomUUID().toString(); private final boolean preparationEnabled;
 public CodingEvaluationJobService(CodingEvaluationJobRepository jobs,AssessmentSnapshotClient snapshots,QuestionCodingSpecClient specs,RunnerExecutionClient runner,@Value("${evaluation.preparation.enabled:true}")boolean preparationEnabled){this.jobs=jobs;this.snapshots=snapshots;this.specs=specs;this.runner=runner;this.preparationEnabled=preparationEnabled;}
 @Transactional public CodingEvaluationJob accept(UUID attemptId,int position,UUID questionId,UUID versionId,String fingerprint,String language){if((fingerprint==null)!=(language==null))throw new IllegalArgumentException("Fingerprint and language must be supplied together");return jobs.findByAttemptIdAndGlobalPositionAndQuestionVersionIdAndSubmittedResponseFingerprint(attemptId,position,versionId,fingerprint).orElseGet(()->jobs.save(CodingEvaluationJob.received(attemptId,position,questionId,versionId,fingerprint,language,clock.instant())));}
 @Scheduled(fixedDelayString="${evaluation.preparation.fixed-delay-ms:5000}") public void poll(){if(!preparationEnabled)return;for(CodingEvaluationJob job:claim(20))prepare(job.jobId());for(CodingEvaluationJob job:claimRunnable(20))dispatch(job.jobId());}
 @Transactional public List<CodingEvaluationJob> claim(int limit){Instant now=clock.instant();List<CodingEvaluationJob> list=jobs.claimable(now,limit);list.forEach(j->j.claim(owner,now.plusSeconds(30),now));return List.copyOf(list);}
 @Transactional public List<CodingEvaluationJob> claimRunnable(int limit){Instant now=clock.instant();List<CodingEvaluationJob> list=jobs.runnable(now,limit);list.forEach(j->j.running(owner,now.plusSeconds(60),now));return List.copyOf(list);}
 public void prepare(UUID id){CodingEvaluationJob job=jobs.findById(id).orElseThrow();try{AssessmentSnapshotClient.Snapshot snapshot=snapshots.get(job.attemptId(),job.globalPosition());validateSnapshot(job,snapshot);if(snapshot.unanswered()){readyForResult(id);return;}QuestionCodingSpecClient.Spec spec=specs.resolve(job.questionVersionId());validateSpec(job,spec);/* Build but deliberately do not dispatch this transient runner request in Phase 2. */ new RunnerJobPreparation(job.jobId(),job.programmingLanguage(),spec.runtimeProfileId(),snapshot.sourceCode(),spec.executionLimits(),spec.testSpecification(),spec.testSpecification().path("comparison"),spec.scoringPolicy());readyForRunner(id);}catch(RemoteDependencyException e){retryOrFail(id,e.category());}catch(IllegalStateException e){fail(id,"INTEGRITY_OR_SPEC_INVALID");}}
 public void dispatch(UUID id){CodingEvaluationJob job=jobs.findById(id).orElseThrow();try{AssessmentSnapshotClient.Snapshot snapshot=snapshots.get(job.attemptId(),job.globalPosition());validateSnapshot(job,snapshot);QuestionCodingSpecClient.Spec spec=specs.resolve(job.questionVersionId());validateSpec(job,spec);RunnerExecutionClient.Result result=runner.execute(toRunnerRequest(job,snapshot,spec));if(!"COMPLETED".equals(result.status()))throw new RemoteDependencyException("RUNNER_INFRASTRUCTURE_FAILURE",null);runnerCompleted(id,result);}catch(RemoteDependencyException e){retryOrFail(id,e.category());}catch(IllegalStateException e){fail(id,"INTEGRITY_OR_SPEC_INVALID");}}
 private static RunnerExecutionClient.Request toRunnerRequest(CodingEvaluationJob job,AssessmentSnapshotClient.Snapshot snapshot,QuestionCodingSpecClient.Spec spec){var limits=spec.executionLimits();var tests=spec.testSpecification().path("hiddenTests");if(!tests.isArray())throw new IllegalStateException();List<RunnerExecutionClient.TestCase> cases=new ArrayList<>();for(var test:tests)cases.add(new RunnerExecutionClient.TestCase(test.path("input").asText(),test.path("output").asText(),spec.testSpecification().path("comparison").path("mode").asText()));return new RunnerExecutionClient.Request(job.jobId(),job.programmingLanguage(),spec.runtimeProfileId(),snapshot.sourceCode(),new RunnerExecutionClient.Limits(limits.path("compileTimeoutMs").asLong(),limits.path("executionTimeoutMs").asLong(),limits.path("memoryMb").asInt(),limits.path("maxOutputBytes").asInt(),64),cases);}
 private static void validateSnapshot(CodingEvaluationJob j,AssessmentSnapshotClient.Snapshot s){if(!j.attemptId().equals(s.attemptId())||j.globalPosition()!=s.globalPosition()||!j.questionId().equals(s.questionId())||!j.questionVersionId().equals(s.questionVersionId()))throw new IllegalStateException();if(s.unanswered()){if(j.submittedResponseFingerprint()!=null||j.programmingLanguage()!=null||s.sourceCode()!=null)throw new IllegalStateException();return;}if(!Objects.equals(j.programmingLanguage(),s.programmingLanguage())||!Objects.equals(j.submittedResponseFingerprint(),s.sourceFingerprint())||!Objects.equals(j.submittedResponseFingerprint(),sha256(s.sourceCode())))throw new IllegalStateException();}
 private static void validateSpec(CodingEvaluationJob j,QuestionCodingSpecClient.Spec s){if(!"JAVA".equals(j.programmingLanguage())||!s.allowedProgrammingLanguages().toString().contains("JAVA")||s.testSpecification()==null||s.testSpecification().path("hiddenTests").isMissingNode())throw new IllegalStateException();}
 private static String sha256(String source){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(source.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional void readyForRunner(UUID id){CodingEvaluationJob j=jobs.findById(id).orElseThrow();j.readyForRunner(clock.instant());jobs.save(j);}
 @Transactional void readyForResult(UUID id){CodingEvaluationJob j=jobs.findById(id).orElseThrow();j.readyForResultApplication(clock.instant());jobs.save(j);}
 @Transactional void runnerCompleted(UUID id,RunnerExecutionClient.Result result){CodingEvaluationJob j=jobs.findById(id).orElseThrow();j.runnerCompleted(result.candidateFailureCategory(),result.testsPassed(),result.testsTotal(),result.executionTimeMs(),clock.instant());jobs.save(j);}
 @Transactional void retryOrFail(UUID id,String category){CodingEvaluationJob j=jobs.findById(id).orElseThrow();Instant now=clock.instant();if(j.retryCount()>=5)j.fail(category,now);else j.retry(category,now.plusSeconds(Math.min(300,1L<<Math.min(8,j.retryCount()+1))),now);jobs.save(j);}
 @Transactional void fail(UUID id,String category){CodingEvaluationJob j=jobs.findById(id).orElseThrow();j.fail(category,clock.instant());jobs.save(j);}
}
